window.__pfUntil=async(fn,ms=20000)=>{const end=Date.now()+ms;while(Date.now()<end){try{if(await fn())return true;}catch{}await new Promise(resolve=>setTimeout(resolve,40));}return false;};
window.__pfBaseApi=api;window.__pfErrors=[];window.__pfRecordReads=0;
addEventListener('error',event=>__pfErrors.push(event.message));addEventListener('unhandledrejection',event=>__pfErrors.push(String(event.reason)));
window.__pfPost=(path,body)=>__pfBaseApi(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
window.__pfCards=()=>[...document.querySelectorAll('#gallery .card[data-id]')];
window.__pfKnown=()=>JSON.parse(sessionStorage.getItem('auradream.smoke.picked-favorites'));
window.__pfNotAliased=(ids)=>[viewerRecords,sessionRecords,lbList].every(list=>list.every(rec=>!ids.includes(rec.id)));
window.__pfTagPicks=()=>{const known=__pfKnown();for(const[index,id]of known.picks.entries()){const card=document.querySelector('#gallery .card[data-id="'+id+'"]');if(!card)throw Error('Missing owned fixture card #'+id);card.dataset.pfPick=index===0?'first':'second';}};
window.__pfPromptState=()=>JSON.stringify({prompt:els.prompt.value,negative:els.negative.value});
window.__pfServer=async(ids)=>Promise.all(ids.map(id=>__pfBaseApi('/api/images/'+id)));
api=async(path,options)=>{if(new RegExp('^/api/images/[0-9]+$').test(path.split('?')[0]))__pfRecordReads++;return __pfBaseApi(path,options);};

(async()=>{
if((await __pfBaseApi('/api/gallery')).total!==0)throw Error('This smoke requires fresh scratch --data for the selected FLUX.1 model.');
const wait=async(job)=>{const done=await __pfUntil(async()=>{const state=await __pfBaseApi('/api/jobs/'+job);return !['queued','running'].includes(state.status);});if(!done)throw Error('Owned fake fixture did not finish.');};
const first=await __pfPost('/api/generate',{prompt:'owned older picked favorite fixture',width:256,height:256,steps:1,seed:7100,num_images:2});await wait(first.job_id);
const second=await __pfPost('/api/generate',{prompt:'owned newer gallery decoy',width:256,height:256,steps:1,seed:7200,num_images:1});await wait(second.job_id);
const rows=(await __pfBaseApi('/api/gallery?limit=100')).items.sort((a,b)=>a.id-b.id);
if(rows.length!==3)throw Error('Expected exactly three owned fake images.');
sessionStorage.setItem('auradream.smoke.picked-favorites',JSON.stringify({picks:rows.slice(0,2).map(rec=>rec.id),decoy:rows[2].id}));
})()

